def solve_first(max_nodes=2_000_000):
 calls=0; dead=set(); path=[]
 # area of each type
 areas=[h*w for h,w,q,n in types]
 @lru_cache(None)
 def rec(filled, counts):
  nonlocal calls
  calls+=1
  if calls>max_nodes: raise RuntimeError('max nodes')
  if filled==fullmask:
   return () if not any(counts) else None
  # area validation
  rem_count=sum(counts[i]*areas[i] for i in range(len(types)))
  if rem_count != len(target)-filled.bit_count(): return None
  # choose uncovered cell with fewest feasible placements, considering type counts
  best=None; bestopts=None
  missing=fullmask ^ filled
  while missing:
   bit=missing & -missing; ci=bit.bit_length()-1; missing-=bit
   opts=[]
   for ti,oi,m in bycell[ci]:
    if counts[ti] and not (m&filled):
     opts.append((ti,oi,m))
   if bestopts is None or len(opts)<len(bestopts):
    best=ci;bestopts=opts
    if not opts: return None
    if len(opts)==1: break
  # big pieces first, fewer future constraints? sort by tile area then type option count
  bestopts.sort(key=lambda x: (-areas[x[0]], len(placements[x[0]])))
  for ti,oi,m in bestopts:
   nc=list(counts);nc[ti]-=1
   ans=rec(filled|m,tuple(nc))
   if ans is not None:
    return ((ti,oi),)+ans
  return None
 ans=rec(0,init_counts)
 return ans,calls,rec.cache_info()
